// What the organization may use now (PRD LIC-01 to LIC-05): its edition and
// state, features and limits as devices receive them signed in bundles, seats
// counted as active developers (people whose devices sent events in the last 30
// days), its subscription, and what it can buy. Features are checked by key,
// never by edition.
type License struct {
	Edition LicenseEdition `json:"edition"`

	// grace: past valid_until, everything still works until grace_ends_at, then
	// the organization is downgraded to free.
	State    LicenseState    `json:"state"`
	Features map[string]bool `json:"features"`

	// null means unlimited.
	Limits entitlements.EntitlementsLimits `json:"limits"`

	// RFC 3339 in UTC with exactly three fractional digits, for example
	// 2026-10-23T09:14:02.481Z.
	ValidFrom contract.Time `json:"valid_from"`

	// Absent for the free edition.
	ValidUntil *contract.Time `json:"valid_until,omitempty"`
	GraceDays  int64          `json:"grace_days"`

	// RFC 3339 in UTC with exactly three fractional digits, for example
	// 2026-10-23T09:14:02.481Z.
	GraceEndsAt  *contract.Time       `json:"grace_ends_at,omitempty"`
	Seats        LicenseSeats         `json:"seats"`
	Subscription *LicenseSubscription `json:"subscription,omitempty"`

	// What the organization can buy now, from the providers this region has set
	// up; empty when self-serve billing is off.
	Offers []LicenseOffer `json:"offers"`
}

// LicenseEdition is generated from org-api/v1/messages.schema.json#/$defs/License/properties/edition.
type LicenseEdition string

// Values of LicenseEdition.
const (
	LicenseEditionFree       LicenseEdition = "free"
	LicenseEditionTrial      LicenseEdition = "trial"
	LicenseEditionTeam       LicenseEdition = "team"
	LicenseEditionEnterprise LicenseEdition = "enterprise"
)

// LicenseState is generated from org-api/v1/messages.schema.json#/$defs/License/properties/state.
//
// grace: past valid_until, everything still works until grace_ends_at, then the
// organization is downgraded to free.
type LicenseState string

// Values of LicenseState.
const (
	LicenseStateActive  LicenseState = "active"
	LicenseStateTrial   LicenseState = "trial"
	LicenseStateGrace   LicenseState = "grace"
	LicenseStateExpired LicenseState = "expired"
)

// LicenseSeats is generated from org-api/v1/messages.schema.json#/$defs/License/properties/seats.
type LicenseSeats struct {
	// Absent when unlimited.
	Limit  *int64 `json:"limit,omitempty"`
	Active int64  `json:"active"`

	// RFC 3339 in UTC with exactly three fractional digits, for example
	// 2026-10-23T09:14:02.481Z.
	CountedAt *contract.Time `json:"counted_at,omitempty"`

	// When active developers first exceeded the limit, while they still do.
	OverageSince *contract.Time `json:"overage_since,omitempty"`

	// RFC 3339 in UTC with exactly three fractional digits, for example
	// 2026-10-23T09:14:02.481Z.
	OverageGraceEndsAt *contract.Time `json:"overage_grace_ends_at,omitempty"`

	// New devices are refused (seat-limit-reached) because the overage outlasted
	// its grace period, or (not-entitled) because the edition has no cloud_sync.
	// Enrolled devices keep working.
	EnrollmentBlocked bool `json:"enrollment_blocked"`
}

